heal.source:
script heal(service) {
  let host = host_of(service)
  if log_tail(service) == "no space left on device" {
    clear_tmp(host)
  } else {
    reboot_host(host)
  }
  restart(service)
}

script heal(service) {
  let host = host_of(service)
  let port = ask("pick a free port on " + host)
  set_config(service, "port", port)
  restart(service)
}

script heal(service) {
  let host = host_of(service)
  let cfg = config(service)
  if contains(ports_in_use(host), cfg.port) {
    set_config(service, "port", cfg.port + 1)
  }
  restart(service)
}

script heal(service) {
  let host = host_of(service)
  let cfg = config(service)
  let port = cfg.listen.port
  if contains(ports_in_use(host), port) {
    set_config(service, "listen", {port: port + 1})
  }
  restart(service)
}

recover_host.source:
script recover_host(host) {
  for s in services_on(host) {
    use heal(s)
  }
}
